BEGIN;

-- Lenny Pimentel biography — link Grupo Grace.
--
-- The biography created in 20260825030000 named Grupo Grace as plain text in
-- both locales. Grupo Grace is a published artist in the catalogue, and
-- EDITORIAL_BIOGRAPHY_FORMAT.md requires any catalogued artist mentioned in a
-- biography to be an artistReference node with a matching relation row.
--
-- The integrity report did not catch this: it verifies that reference nodes
-- and relation rows agree, not that plain text failed to become a reference in
-- the first place. Hope W Music, Israel Martínez and Benny Martínez are also
-- named in the biography and are correctly left as plain text — none of them
-- is in the catalogue.
--
-- The markdown mirror is unchanged: a reference renders as its displayText
-- unadorned, which is the text already stored.

-- en
UPDATE editorial_documents
SET document = $json${"type":"doc","content":[{"type":"paragraph","content":[{"text":"Lenny Pimentel, who also records as Lenny Piment, is a Dominican worship singer, songwriter and producer who spent roughly nine years inside the merenhouse group ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1cd11a22-573a-43b4-8f54-fbd08329a4e2","displayText":"Ilegales","occurrenceId":"d0f59d48-0750-45cd-b3ab-576ba3618881"}},{"text":" before leaving commercial music for the church. He pastors Casa de Dios La Hermosa in Baní and has released worship records steadily since 2020, writing from his own experience rather than to a devotional formula.","type":"text"}]},{"type":"paragraph","content":[{"text":"The Ilegales years","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Pimentel worked as a writer and vocalist with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1cd11a22-573a-43b4-8f54-fbd08329a4e2","displayText":"Ilegales","occurrenceId":"8623dbaf-c315-4e8a-9610-3837d36dcae5"}},{"text":", the group formed in 1993 that pushed merenhouse past the Dominican market and onto international charts with records such as La Morena and El Taqui Taqui. He is listed among its former members and spent about nine years with the group, contributing compositions as well as voice. Accounts of this period also credit him with writing for other artists working in commercial Latin music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Conversion and Casa de Dios La Hermosa","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He left the group and secular music altogether for pastoral work. With his family he leads Casa de Dios La Hermosa, a congregation in Baní, in the province of Peravia. Ministry and recording have run together since: he has described his songs as arriving out of what he was living through at the time, each one tied to a particular passage rather than written to order.","type":"text"}]},{"type":"paragraph","content":[{"text":"Worship recordings","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His first Christian project appeared in 2018 — an album of ten songs produced by Israel Martínez, with Benny Martínez as co-producer, introduced by the single Aún no has terminado and the video Muestra Tu Poder.","type":"text"}]},{"type":"paragraph","content":[{"text":"A second and more sustained run began with Demasiado, released on 16 November 2020 and written during the COVID-19 pandemic. Encuéntrame followed in 2021 as part of the EP Uno Más. The 2023 releases include Movimiento, a collaboration with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"629a7daa-5ab3-4b77-825f-6795b8c4a566","displayText":"Marcos Yaroide","occurrenceId":"b9d4d6ec-18d7-4d59-ae81-3658fc9fd959"}},{"type":"text","text":" that carried across Latin American Christian radio, alongside the live single Betesda, Consúmenos with "},{"type":"artistReference","attrs":{"occurrenceId":"7f27abb8-336b-4fe4-8cf0-9066b44ac5c3","artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace"}},{"type":"text","text":", and the live EP Tu Presencia Vale Más."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Demasiado — single, 2020","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Encuéntrame — single, 2021, from the EP Uno Más","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Betesda (Live) — single with Hope W Music, 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Movimiento — single with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"629a7daa-5ab3-4b77-825f-6795b8c4a566","displayText":"Marcos Yaroide","occurrenceId":"c48fb973-54c2-4666-a861-c248f7369879"}},{"text":", 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consúmenos — single with "},{"type":"artistReference","attrs":{"occurrenceId":"9c12a1f4-bbc6-43e0-ad83-138c6b7e29bd","artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace"}},{"type":"text","text":", 2023"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tu Presencia Vale Más (Live) — EP, 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"De mi casa se acordó Jehová — single, 2025","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Más Grande — single, 2025","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A Donde Huiré — single, 6 November 2025","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Pimentel's route — from a merenhouse group with international records to a pulpit in Baní — is among the clearer Dominican cases of a commercial songwriter moving wholly into worship music and staying productive there. He did not trade recording for ministry but kept both, and the catalogue he has built since 2020 is the work of someone still writing, not a figure retired into the pastorate.","type":"text"}]}]}$json$::jsonb,
    revision = 2,
    updated_at = now()
WHERE id = 'c486f572-a63f-4157-affe-c28afda33009';

