VALUES ('c486f572-a63f-4157-affe-c28afda33009', '9c12a1f4-bbc6-43e0-ad83-138c6b7e29bd', 'artist', '43a14bc5-52fd-43df-9bd9-15f3b11dcf3b');

-- es
UPDATE editorial_documents
SET document = $json${"type":"doc","content":[{"type":"paragraph","content":[{"text":"Lenny Pimentel, que también graba como Lenny Piment, es un cantante de alabanza, compositor y productor dominicano que pasó cerca de nueve años en la agrupación de merenhouse ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1cd11a22-573a-43b4-8f54-fbd08329a4e2","displayText":"Ilegales","occurrenceId":"eb5d55a6-0374-44e2-9277-2a9bbcc7417c"}},{"text":" antes de dejar la música comercial por la iglesia. Pastorea Casa de Dios La Hermosa, en Baní, y desde 2020 publica música de adoración con regularidad, escribiendo desde lo vivido y no desde una fórmula devocional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los años en Ilegales","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Pimentel trabajó como compositor y vocalista en ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1cd11a22-573a-43b4-8f54-fbd08329a4e2","displayText":"Ilegales","occurrenceId":"293827b8-944a-4b44-af28-de37714bd967"}},{"text":", el grupo formado en 1993 que llevó el merenhouse más allá del mercado dominicano hasta las listas internacionales con temas como La Morena y El Taqui Taqui. Figura entre sus integrantes anteriores y estuvo cerca de nueve años en la agrupación, aportando composiciones además de voz. Los relatos de esa etapa también le atribuyen haber escrito para otros artistas de la música latina comercial.","type":"text"}]},{"type":"paragraph","content":[{"text":"Conversión y Casa de Dios La Hermosa","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Dejó el grupo y la música secular por completo para dedicarse al trabajo pastoral. Junto a su familia dirige Casa de Dios La Hermosa, una congregación de Baní, en la provincia de Peravia. Desde entonces el ministerio y la grabación caminan juntos: ha explicado que sus canciones surgen de lo que estaba atravesando en cada momento, atadas a un episodio concreto y no escritas por encargo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Grabaciones de alabanza","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su primer proyecto cristiano apareció en 2018: un disco de diez canciones producido por Israel Martínez, con Benny Martínez como coproductor, presentado con el sencillo Aún no has terminado y el video Muestra Tu Poder.","type":"text"}]},{"type":"paragraph","content":[{"text":"Una segunda etapa, más sostenida, empezó con Demasiado, publicado el 16 de noviembre de 2020 y escrito durante la pandemia de COVID-19. Encuéntrame llegó en 2021 como parte del EP Uno Más. Entre los lanzamientos de 2023 está Movimiento, una colaboración con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"629a7daa-5ab3-4b77-825f-6795b8c4a566","displayText":"Marcos Yaroide","occurrenceId":"10cb9aa9-f856-4f9a-83a9-d5cfe7923fa5"}},{"type":"text","text":" que sonó en la radio cristiana latinoamericana, junto al sencillo en vivo Betesda, Consúmenos con "},{"type":"artistReference","attrs":{"occurrenceId":"8060a2f6-ef87-49f5-a5b1-42d295c93224","artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace"}},{"type":"text","text":" y el EP en vivo Tu Presencia Vale Más."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Demasiado — sencillo, 2020","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Encuéntrame — sencillo, 2021, del EP Uno Más","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Betesda (En vivo) — sencillo con Hope W Music, 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Movimiento — sencillo con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"629a7daa-5ab3-4b77-825f-6795b8c4a566","displayText":"Marcos Yaroide","occurrenceId":"78cba011-1751-4add-8567-61955d7bffe5"}},{"text":", 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consúmenos — sencillo con "},{"type":"artistReference","attrs":{"occurrenceId":"421e063b-e8ba-47b5-b106-7d24827a85db","artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace"}},{"type":"text","text":", 2023"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tu Presencia Vale Más (En vivo) — EP, 2023","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"De mi casa se acordó Jehová — sencillo, 2025","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Más Grande — sencillo, 2025","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A Donde Huiré — sencillo, 6 de noviembre de 2025","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El recorrido de Pimentel —de una agrupación de merenhouse con discos internacionales a un púlpito en Baní— es uno de los casos dominicanos más nítidos de un compositor comercial que se pasa por entero a la música de adoración y sigue produciendo allí. No cambió la grabación por el ministerio sino que conservó ambos, y el catálogo que ha levantado desde 2020 es el de alguien que sigue escribiendo, no el de una figura retirada al pastorado.","type":"text"}]}]}$json$::jsonb,
    revision = 2,
    updated_at = now()
WHERE id = '7d349801-eb29-4a5b-96e4-f2d0a5f6730b';

